    (1762000000001000020, 'randomFail', '随机失败', null, 'PLATFORM', 'other', 'common', 'ph:dice-five', '#f56c6c', 60, '测试专用：每次执行按 failRate 概率随机抛异常，自然产生成功/失败混合序列，用于反复验证监控告警触发与恢复；生产链路勿用', 'NODE', 'form', '{"fields":[{"name":"failRate","label":"失败概率","description":"0到1之间，每次执行按该概率抛异常；不填默认0.5。连错3次触发告警后出现成功即自动恢复","widget":"NUMBER","required":false,"order":1,"placeholder":"0.5","valueExprRole":"LITERAL"}]}', '{"failRate":0.5}', 'java', 'package org.dromara.databus.script;\n\nimport java.util.concurrent.ThreadLocalRandom;\nimport lombok.Data;\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n/**\n * 随机失败组件（注册名 randomFail）——告警验收专用故障制造机，生产链路勿用。\n * 每次执行取 [0,1) 随机数，小于 failRate 就抛 ServiceException，否则正常通过；\n * 自然形成成功/失败混合序列，可反复验证告警的触发、防抖与自动恢复。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "randomFail",\n    name = "随机失败",\n    icon = "ph:dice-five",\n    color = "#f56c6c",\n    group = "other",\n    sort = 60,\n    description = "测试专用：每次执行按 failRate 概率随机抛异常，自然产生成功/失败混合序列，用于反复验证监控告警触发与恢复；生产链路勿用",\n    dataExample = """\n        {"failRate":0.5}\n        """\n)\npublic class RandomFailComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        RandomFailCfg cfg = this.getCmpData(RandomFailCfg.class);\n        double rate = (cfg == null || cfg.getFailRate() == null) ? 0.5d : cfg.getFailRate();\n        rate = Math.max(0d, Math.min(1d, rate));\n        double roll = ThreadLocalRandom.current().nextDouble();\n        if (roll < rate) {\n            log.info("[databus] randomFail 命中失败 roll={} rate={}", roll, rate);\n            throw new ServiceException("告警测试：随机失败（随机数 " + String.format("%.2f", roll) + " 小于失败概率 " + rate + "）");\n        }\n        resultSummary("随机通过（随机数 " + String.format("%.2f", roll) + "，失败概率 " + rate + "）");\n        log.info("[databus] randomFail 通过 roll={} rate={}", roll, rate);\n    }\n\n    @Data\n    public static class RandomFailCfg {\n\n        @DatabusProp(\n            label = "失败概率",\n            widget = WidgetKind.NUMBER,\n            order = 1,\n            placeholder = "0.5",\n            description = "0到1之间，每次执行按该概率抛异常；不填默认0.5。取0.5时自然形成成败交替，连错3次触发告警后出现成功即自动恢复"\n        )\n        private Double failRate;\n    }\n}\n', 1, '0', '0', sysdate(), @db_seed_test_did, @db_seed_test_uid),
    (1762000000001000022, 'dbQuery', '数据库查询', '库查询', 'PLATFORM', 'business', 'db', 'ph:magnifying-glass', '#409eff', 230, '在连接指向的数据库上执行查询 SQL：多行/首行/标量三种结果模式，条件值用 ? 占位由参数绑定，结果存 $.数据空间.rows|row|value', 'NODE', 'form', '{"fields":[{"name":"connectionId","label":"连接","description":"数据库连接实例；下拉只列 family=jdbc 的连接，具体是哪种库由该连接的连接器类型决定","widget":"CONNECTION_SELECT","required":true,"exprRole":"LITERAL","order":1,"valueExprRole":"LITERAL","connectorFamily":"jdbc"},{"name":"sql","label":"查询 SQL","description":"SQL 原样透传不求值；条件值一律用 ? 占位，由「SQL 参数」按顺序绑定（不要拼字符串）","widget":"TEXTAREA","required":true,"exprRole":"LITERAL","placeholder":"select userid, name from orguser where deptid = ?","order":2,"valueExprRole":"LITERAL"},{"name":"args","label":"SQL 参数","description":"JSON 数组，元素为字面量或 {{ $.路径 }} 表达式，与 ? 占位顺序一致","widget":"JSON","required":false,"exprRole":"LITERAL","order":3,"valueExprRole":"LITERAL"},{"name":"resultMode","label":"结果模式","description":"rows 多行（缺省）/ first 首行 / scalar 首行首列标量","widget":"SELECT","required":false,"exprRole":"LITERAL","order":4,"options":[{"label":"多行 rows","value":"rows"},{"label":"首行 first","value":"first"},{"label":"标量 scalar","value":"scalar"}],"valueExprRole":"LITERAL"},{"name":"scalarType","label":"标量类型","description":"仅「结果模式=标量」时生效；缺省按数据库返回类型原样输出","widget":"SELECT","required":false,"exprRole":"LITERAL","order":5,"options":[{"label":"字符串 string","value":"string"},{"label":"整数 int","value":"int"},{"label":"长整数 long","value":"long"},{"label":"浮点 double","value":"double"}],"showWhen":[{"field":"resultMode","eq":"scalar"}],"valueExprRole":"LITERAL"},{"name":"maxRows","label":"最大行数","description":"留空由连接器缺省；超过硬上限 10000 会被压到上限并告警","widget":"NUMBER","required":false,"exprRole":"LITERAL","order":6,"valueExprRole":"LITERAL"},{"name":"fetchSize","label":"抓取大小","description":"JDBC fetchSize，留空缺省 100","widget":"NUMBER","required":false,"exprRole":"LITERAL","order":7,"valueExprRole":"LITERAL"}]}', '{"connectionId":"jdbc-default","sql":"select userid, name from orguser where deptid = ?","args":["{{ $.request.deptId }}"],"resultMode":"rows","maxRows":100}\n', 'java', 'package org.dromara.databus.script;\n\nimport lombok.Data;\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.Connector;\nimport org.dromara.databus.connector.ConnectorRegistry;\nimport org.dromara.databus.connector.sql.QueryOptions;\nimport org.dromara.databus.connector.sql.QueryResult;\nimport org.dromara.databus.connector.sql.SqlConnector;\nimport java.util.ArrayList;\nimport java.util.List;\n\n/**\n * 数据库查询组件（注册名 {@code dbQuery}）。\n * <p>\n * 在「连接」指向的数据库上执行查询 SQL，走 {@link SqlConnector} 能力接口——脚本里没有任何\n * 具体连接器类名（{@code jdbc-postgresql} / {@code jdbc-oracle} 由连接行的 connectorType 决定，\n * 运行时从注册表取实例，因此连接器热更新不断链路）。\n *\n * <p>三种结果模式（{@code resultMode}）：\n * <ul>\n *   <li>{@code rows}（缺省）：多行 → {@code $.<tag>.rows}（List&lt;Map&gt;）</li>\n *   <li>{@code first}：首行 → {@code $.<tag>.row}（Map，未命中为 null）</li>\n *   <li>{@code scalar}：首行首列标量 → {@code $.<tag>.value}，类型由 {@code scalarType} 决定</li>\n * </ul>\n * {@code rowCount}（不受 maxRows 截断影响）与 {@code columns} 三种模式下都产出。\n *\n * <p><b>SQL 原样透传不求值</b>：条件值一律写 {@code ?} 占位、由 args 按顺序绑定，\n * 与 {@code rdsExecute} 同构，不构成新增注入面（jdbc-connector-plan §9.2）。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = \"dbQuery\", name = \"数据库查询\", shortName = \"库查询\",\n    icon = \"ph:magnifying-glass\", color = \"#409eff\",\n    description = \"在连接指向的数据库上执行查询 SQL：多行/首行/标量三种结果模式，条件值用 ? 占位由参数绑定，结果存 $.数据空间.rows|row|value\", sort = 230,\n    dataExample = \"\"\"\n        {\"connectionId\":\"jdbc-default\",\"sql\":\"select userid, name from orguser where deptid = ?\",\"args\":[\"{{ $.request.deptId }}\"],\"resultMode\":\"rows\",\"maxRows\":100}\n        \"\"\"\n)\npublic class DbQueryComponent extends DatabusNodeComponent {\n\n    /** resultMode 缺省值：多行。 */\n    private static final String DEFAULT_RESULT_MODE = \"rows\";\n\n    @Override\n    public void process() {\n        DbQueryCfg cfg = this.getCmpData(DbQueryCfg.class);\n        String tag = this.getTag();\n        if (cfg == null) {\n            throw new ServiceException(\"数据库查询组件缺少参数配置（tag=\" + tag + \"）\");\n        }\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException(\"数据库查询组件缺少数据空间标识（tag）\");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException(\"数据库查询组件缺少 connectionId 配置（tag=\" + tag + \"）\");\n        }\n        if (cfg.getSql() == null || cfg.getSql().isBlank()) {\n            throw new ServiceException(\"数据库查询组件缺少 sql 配置（tag=\" + tag + \"）\");\n        }\n        String resultMode = cfg.getResultMode() == null || cfg.getResultMode().isBlank()\n                ? DEFAULT_RESULT_MODE : cfg.getResultMode();\n\n        Connection conn = getDatabusContext().getConnection(cfg.getConnectionId());\n        // columnNameCase 不开放给编排者：列名大小写归一是连接器/库方言的事（Oracle、达梦默认大写），\n        // 由连接器按 descriptor 缺省值处理，组件侧恒传 null（jdbc-connector-plan §7.1/§8.1）\n        QueryOptions opts = new QueryOptions(resultMode, cfg.getScalarType(),\n                cfg.getMaxRows(), cfg.getFetchSize(), null);\n        QueryResult result = sqlConnector(conn, tag)\n                .query(conn, cfg.getSql(), resolveArgList(cfg.getArgs()), opts);\n\n        save(\"$.\" + tag + \".rows\", result.rows());\n        save(\"$.\" + tag + \".row\", result.row());\n        save(\"$.\" + tag + \".value\", result.value());\n        save(\"$.\" + tag + \".rowCount\", result.rowCount());\n        save(\"$.\" + tag + \".columns\", result.columns());\n        resultSummary(buildSummary(resultMode, result));\n        log.info(\"[databus] dbQuery 完成 tag={} connId={} resultMode={} rowCount={}\",\n                tag, conn.getId(), resultMode, result.rowCount());\n    }\n\n    /**\n     * 按 resultMode 生成步骤人话摘要：多行报返回行数、首行报是否命中、标量报取值。\n     */\n    private String buildSummary(String resultMode, QueryResult result) {\n        return switch (resultMode) {\n            case \"scalar\" -> \"取值：\" + result.value();\n            case \"first\" -> result.row() == null\n                    ? \"查询未命中行\" : \"查询命中 1 行（命中总数 \" + result.rowCount() + \"）\";\n            default -> \"查询返回 \" + (result.rows() == null ? 0 : result.rows().size())\n                    + \" 行（命中总数 \" + result.rowCount() + \"）\";\n        };\n    }\n\n    /**\n     * 取 SQL 能力连接器：注册表按连接行的 connectorType 查实例后强转 {@link SqlConnector}。\n     * <p>\n     * 每次 process 都重新取（不缓存到字段），这是连接器热更新能不断链路的前提。\n     * 连接指向非 SQL 族连接器（如 bpmHttp）时给出可诊断的报错，而不是 ClassCastException。\n     */\n    private SqlConnector sqlConnector(Connection conn, String tag) {\n        Connector connector = SpringUtils.getBean(ConnectorRegistry.class).ofType(conn.getConnectorType());\n        if (!(connector instanceof SqlConnector sqlConnector)) {\n            throw new ServiceException(\"数据库查询组件的连接 \" + conn.getId() + \" 指向连接器 \"\n                    + conn.getConnectorType() + \"，它不提供 SQL 能力（本组件需要 family=jdbc 的连接，tag=\" + tag + \"）\");\n        }\n        return sqlConnector;\n    }\n\n    /**\n     * args 解析为绑定参数列表：List 逐元素递归（元素可为 {@code {{ $.路径 }}} 表达式），\n     * 叶子走 resolveParam；裸标量容错为单元素列表。\n     */\n    private List<Object> resolveArgList(Object args) {\n        if (args == null) {\n            return new ArrayList<>();\n        }\n        Object resolved = resolveArgs(args);\n        if (resolved == null) {\n            return new ArrayList<>();\n        }\n        if (resolved instanceof List<?> list) {\n            List<Object> result = new ArrayList<>(list.size());\n            for (Object item : list) {\n                result.add(item);\n            }\n            return result;\n        }\n        List<Object> single = new ArrayList<>(1);\n        single.add(resolved);\n        return single;\n    }\n\n    /**\n     * args 递归解析（复用 rdsExecute 范式）：List 逐元素递归，叶子走 resolveParam\n     * （字面量原样返回 / {@code {{ $.路径 }}} 整字段求值保留原类型）。\n     */\n    private Object resolveArgs(Object args) {\n        if (args instanceof List<?> list) {\n            List<Object> resolved = new ArrayList<>(list.size());\n            for (Object item : list) {\n                resolved.add(resolveArgs(item));\n            }\n            return resolved;\n        }\n        return resolveParam(args);\n    }\n\n    /**\n     * 数据库查询组件（dbQuery）的节点参数。\n     * <pre>\n     * {\n     *   \"connectionId\": \"jdbc-default\",              // 必填，family=jdbc 的连接实例\n     *   \"sql\": \"select id, name from t where id=?\",  // 必填，原样透传不求值\n     *   \"args\": [\"{{ $.request.id }}\"],              // 可选，与 ? 占位顺序一致\n     *   \"resultMode\": \"rows\",                        // 可选：rows（缺省）/ first / scalar\n     *   \"scalarType\": \"string\",                      // 仅 scalar 生效：string / int / long / double\n     *   \"maxRows\": 100,                              // 可选，连接器硬上限 10000\n     *   \"fetchSize\": 100                             // 可选，缺省 100\n     * }\n     * </pre>\n     *\n     * <p>产出：{@code $.<tag>.rows} / {@code .row} / {@code .value}（按 resultMode 只有一处有值）、\n     * {@code .rowCount}、{@code .columns}。\n     *\n     * @author databus\n     */\n    @Data\n    public static class DbQueryCfg {\n\n        /** 连接实例 ID（必填，只列 family=jdbc 的连接） */\n        @DatabusProp(\n            label = \"连接\", required = true, widget = WidgetKind.CONNECTION_SELECT,\n            connectorFamily = \"jdbc\", order = 1,\n            description = \"数据库连接实例；下拉只列 family=jdbc 的连接，具体是哪种库由该连接的连接器类型决定\"\n        )\n        private String connectionId;\n\n        /** 查询 SQL（必填，原样透传不走路径求值） */\n        @DatabusProp(\n            label = \"查询 SQL\", required = true, widget = WidgetKind.TEXTAREA, order = 2,\n            placeholder = \"select userid, name from orguser where deptid = ?\",\n            description = \"SQL 原样透传不求值；条件值一律用 ? 占位，由「SQL 参数」按顺序绑定（不要拼字符串）\"\n        )\n        private String sql;\n\n        /** 绑定参数（可选，JSON 数组，元素为字面量或 {{ $.路径 }} 表达式） */\n        @DatabusProp(\n            label = \"SQL 参数\", widget = WidgetKind.JSON, order = 3,\n            description = \"JSON 数组，元素为字面量或 {{ $.路径 }} 表达式，与 ? 占位顺序一致\"\n        )\n        private Object args;\n\n        /** 结果模式：rows 多行 / first 首行 / scalar 标量（可选，缺省 rows） */\n        @DatabusProp(\n            label = \"结果模式\", widget = WidgetKind.SELECT, order = 4,\n            description = \"rows 多行（缺省）/ first 首行 / scalar 首行首列标量\",\n            options = {\n                @DatabusProp.Option(label = \"多行 rows\", value = \"rows\"),\n                @DatabusProp.Option(label = \"首行 first\", value = \"first\"),\n                @DatabusProp.Option(label = \"标量 scalar\", value = \"scalar\")\n            }\n        )\n        private String resultMode;\n\n        /** 标量类型（仅 resultMode=scalar 生效） */\n        @DatabusProp(\n            label = \"标量类型\", widget = WidgetKind.SELECT, order = 5,\n            description = \"仅「结果模式=标量」时生效；缺省按数据库返回类型原样输出\",\n            showWhen = {@DatabusProp.ShowWhen(field = \"resultMode\", eq = \"scalar\")},\n            options = {\n                @DatabusProp.Option(label = \"字符串 string\", value = \"string\"),\n                @DatabusProp.Option(label = \"整数 int\", value = \"int\"),\n                @DatabusProp.Option(label = \"长整数 long\", value = \"long\"),\n                @DatabusProp.Option(label = \"浮点 double\", value = \"double\")\n            }\n        )\n        private String scalarType;\n\n        /** 最大返回行数（可选，连接器硬上限 10000） */\n        @DatabusProp(\n            label = \"最大行数\", order = 6,\n            description = \"留空由连接器缺省；超过硬上限 10000 会被压到上限并告警\"\n        )\n        private Integer maxRows;\n\n        /** 抓取大小（可选，缺省 100） */\n        @DatabusProp(label = \"抓取大小\", order = 7, description = \"JDBC fetchSize，留空缺省 100\")\n        private Integer fetchSize;\n    }\n}\n', 1, '0', '0', sysdate(), @db_seed_test_did, @db_seed_test_uid),
