.connector.sql.SqlConnector;\nimport java.util.ArrayList;\nimport java.util.List;\n\n/**\n * 数据库执行组件（注册名 {@code dbExecute}）。\n * <p>\n * 在「连接」指向的数据库上执行单条写入语句（INSERT / UPDATE / DELETE / DDL），\n * 走 {@link SqlConnector#execute} 能力接口，可选回填自增主键。\n *\n * <p><b>事务边界（jdbc-connector-plan §6.2）</b>：事务只包在本组件内——语句执行完即提交，\n * 异常即回滚。<b>跨节点事务 v1 不支持</b>：链路后续节点失败时本组件已提交的改动不会回滚。\n * 需要「多条语句要么全成要么全不成」请用 {@code dbBatch}（单语句批量参数模式整体一个事务）。\n *\n * <p>SQL 原样透传不求值，条件值一律 {@code ?} 占位由 args 绑定；语句首个关键字记入执行日志\n * （语句类型审计，jdbc-connector-plan §9.1 P1）。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = \"dbExecute\", name = \"数据库执行\", shortName = \"库执行\",\n    icon = \"ph:pencil-simple\", color = \"#e6a23c\",\n    description = \"在连接指向的数据库上执行单条写入 SQL（INSERT/UPDATE/DELETE/DDL），可回填自增主键；事务只包本组件内，跨节点不回滚\", sort = 240,\n    dataExample = \"\"\"\n        {\"connectionId\":\"jdbc-default\",\"sql\":\"update orguser set name = ? where userid = ?\",\"args\":[\"{{ $.request.name }}\",\"{{ $.request.userId }}\"],\"returnGeneratedKeys\":false}\n        \"\"\"\n)\npublic class DbExecuteComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        DbExecuteCfg cfg = this.getCmpData(DbExecuteCfg.class);\n        String tag = this.getTag();\n        if (cfg == null) {\n            throw new ServiceException(\"数据库执行组件缺少参数配置（tag=\" + tag + \"）\");\n        }\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException(\"数据库执行组件缺少数据空间标识（tag）\");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException(\"数据库执行组件缺少 connectionId 配置（tag=\" + tag + \"）\");\n        }\n        if (cfg.getSql() == null || cfg.getSql().isBlank()) {\n            throw new ServiceException(\"数据库执行组件缺少 sql 配置（tag=\" + tag + \"）\");\n        }\n\n        Connection conn = getDatabusContext().getConnection(cfg.getConnectionId());\n        boolean returnKeys = Boolean.TRUE.equals(cfg.getReturnGeneratedKeys());\n        ExecuteResult result = sqlConnector(conn, tag)\n                .execute(conn, cfg.getSql(), resolveArgList(cfg.getArgs()), returnKeys);\n\n        save(\"$.\" + tag + \".affectedRows\", result.affectedRows());\n        save(\"$.\" + tag + \".generatedKeys\", result.generatedKeys());\n        resultSummary(buildSummary(result));\n        // 语句类型审计：只记首个关键字，不记 SQL 原文与参数（脱敏口径见 §7.3）\n        log.info(\"[databus] dbExecute 完成 tag={} connId={} stmtType={} affectedRows={} generatedKeys={}\",\n                tag, conn.getId(), statementType(cfg.getSql()), result.affectedRows(),\n                result.generatedKeys() == null ? 0 : result.generatedKeys().size());\n    }\n\n    /**\n     * 步骤人话摘要：报影响行数，回填了主键时附带主键个数。\n     */\n    private String buildSummary(ExecuteResult result) {\n        List<Object> keys = result.generatedKeys();\n        String suffix = keys == null || keys.isEmpty() ? \"\" : \"，回填主键 \" + keys.size() + \" 个\";\n        return \"执行影响 \" + result.affectedRows() + \" 行\" + suffix;\n    }\n\n    /**\n     * 取 SQL 首个关键字作语句类型（审计用，大写归一）；空/无关键字回 {@code UNKNOWN}。\n     */\n    private String statementType(String sql) {\n        String trimmed = sql.trim();\n        int end = 0;\n        while (end < trimmed.length() && Character.isLetter(trimmed.charAt(end))) {\n            end++;\n        }\n        return end == 0 ? \"UNKNOWN\" : trimmed.substring(0, end).toUpperCase();\n    }\n\n    /**\n     * 取 SQL 能力连接器：注册表按连接行的 connectorType 查实例后强转 {@link SqlConnector}。\n     * <p>\n     * 每次 process 都重新取（不缓存到字段），这是连接器热更新能不断链路的前提。\n     */\n    private SqlConnector sqlConnector(Connection conn, String tag) {\n        Connector connector = SpringUtils.getBean(ConnectorRegistry.class).ofType(conn.getConnectorType());\n        if (!(connector instanceof SqlConnector sqlConnector)) {\n            throw new ServiceException(\"数据库执行组件的连接 \" + conn.getId() + \" 指向连接器 \"\n                    + conn.getConnectorType() + \"，它不提供 SQL 能力（本组件需要 family=jdbc 的连接，tag=\"