    (1762000000001300003, 'boCreate',         'bpmHttp', sysdate()),
    (1762000000001300004, 'boQuery',          'bpmHttp', sysdate()),
    (1762000000001300005, 'boUpdate',         'bpmHttp', sysdate()),
    (1762000000001300006, 'boDelete',         'bpmHttp', sysdate()),
    (1762000000001300007, 'processTerminate', 'bpmHttp', sysdate()),
    (1762000000001300008, 'taskComplete',     'bpmHttp', sysdate()),
    (1762000000001300009, 'rdsExecute',       'bpmHttp', sysdate()),
    (1762000000001300010, 'idCardToUserId',   'bpmHttp', sysdate()),
    (1762000000001300011, 'fileUpload',       'bpmHttp', sysdate()),
    (1762000000001300012, 'fileDownload',     'bpmHttp', sysdate()),
    (1762000000001300013, 'dbQuery',          'jdbc',    sysdate()),
